'use client';

import { useEffect, useRef, useState } from 'react';
import type { Project } from '@/lib/portfolio-data';
import type { WorksWheelItem } from '@/components/ui/works-wheel';

const companies = [{"title": "Nike", "key": "nike", "src": "data:image/png;base64,"}, {"title": "Snap", "key": "snap", "src": "data:image/png;base64,"}, {"title": "Crocs", "key": "crocs", "src": "data:image/png;base64,"}, {"title": "RKS Design", "key": "rks", "src": "data:image/png;base64,"}, {"title": "Veena Studios", "key": "veena", "src": "data:image/png;base64,"}, {"title": "Fleurs et Sel", "key": "fleurs", "src": "data:image/png;base64,"}];

type Props = {
  items: WorksWheelItem[];
  projects: Project[];
  onSelect: (project: Project) => void;
};

export default function ConsultingPanels({ projects, onSelect }: Props) {
  const row = useRef<HTMLDivElement>(null);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (paused || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const timer = window.setInterval(() => {
      const el = row.current;
      if (!el || el.scrollWidth <= el.clientWidth + 2) return;
      const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 4;
      el.scrollTo({ left: atEnd ? 0 : el.scrollLeft + el.clientWidth / 3, behavior: 'smooth' });
    }, 4500);
    return () => window.clearInterval(timer);
  }, [paused]);

  function move(direction: number) {
    setPaused(true);
    const el = row.current;
    if (el) el.scrollBy({ left: direction * el.clientWidth * .7, behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' });
  }

  return (
    <div className="consulting-logos">
      <div className="logo-toolbar">
        <p>Explore the projects behind the logos.</p>
        <div className="logo-controls">
          <button type="button" onClick={() => move(-1)} aria-label="Previous consulting logos">←</button>
          <button type="button" onClick={() => move(1)} aria-label="Next consulting logos">→</button>
        </div>
      </div>
      <div className="logo-row" ref={row} onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)} onTouchStart={() => setPaused(true)} onFocusCapture={() => setPaused(true)} onBlurCapture={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setPaused(false); }} aria-label="Consulting projects">
        {companies.map((company) => {
          const project = projects.find((item) => item.title.toLowerCase().trim() === company.title.toLowerCase());
          return (
            <button key={company.title} className={`company-logo company-${company.key}`} type="button" disabled={!project} aria-label={`View ${company.title} project`} onClick={() => { if (project) onSelect(project); }}>
              <span className="logo-image"><img src={company.src} alt={company.title} draggable={false} /></span>
              <span className="logo-name">{company.title}<span aria-hidden="true">↗</span></span>
            </button>
          );
        })}
      </div>
      <style jsx>{`
        .consulting-logos { width: 100%; min-width: 0; }
        .logo-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin-bottom: 20px; }
        .logo-toolbar p { margin: 0; font-size: 14px; color: var(--muted, #6b7280); }
        .logo-controls { display: flex; gap: 8px; }
        .logo-controls button { width: 34px; height: 34px; border: 0; border-radius: 50%; background: var(--line, #f0f1f3); color: var(--primary, #111827); font-size: 18px; cursor: pointer; }
        .logo-row { display: grid; grid-auto-flow: column; grid-auto-columns: calc((100% - 100px) / 6); gap: 20px; overflow-x: auto; padding: 10px 0 18px; scroll-snap-type: x proximity; scrollbar-width: thin; }
        .company-logo { min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 16px 8px; border: 0; border-radius: 16px; background: transparent; color: var(--primary, #111827); font: inherit; cursor: pointer; scroll-snap-align: start; transition: background 200ms, transform 200ms; }
        .company-logo:hover { background: var(--line, #f3f4f6); transform: translateY(-3px); }
        .company-logo:disabled { opacity: .4; cursor: default; }
        .company-logo:focus-visible, .logo-controls button:focus-visible { outline: 2px solid var(--blue, #6b9dce); outline-offset: -2px; }
        .logo-image { box-sizing: border-box; width: 96px; height: 96px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; padding: 0; overflow: hidden; border-radius: 16px; background: transparent; }
        .logo-image img { display: block; width: 100%; height: 100%; object-fit: contain; border-radius: 0; }
        .company-nike .logo-image img { filter: brightness(0); }
         :global(.dark) .company-nike .logo-image img { filter: brightness(0) invert(1); }
        .company-snap .logo-image img { transform: scale(2.25); }
        .company-nike .logo-image img { transform: scale(1.12); }
        .company-veena .logo-image img { transform: scale(1.15); }
        .company-fleurs .logo-image img { transform: scale(1.08); }
        .logo-name { display: flex; align-items: center; justify-content: center; gap: 7px; font-size: 11px; line-height: 1.5; text-align: center; color: var(--muted, #6b7280); }
        .logo-name span { opacity: 0; transition: opacity 200ms; }
        .company-logo:hover .logo-name span, .company-logo:focus-visible .logo-name span { opacity: 1; }
        @media (max-width: 900px) { .logo-row { grid-auto-columns: calc((100% - 40px) / 3); } }
        @media (max-width: 480px) { .logo-row { grid-auto-columns: calc((100% - 20px) / 2); } .logo-toolbar p { max-width: 220px; line-height: 1.5; } }
        @media (min-width: 901px) { .logo-controls { display: none; } }
        @media (prefers-reduced-motion: reduce) { .company-logo, .logo-name span { transition: none; } .company-logo:hover { transform: none; } }
      `}</style>
    </div>
  );
}
